 panel.addEventListener('pointerenter',()=>clearTimeout(hideTimer));
 d.addEventListener('pointerdown',e=>{if(!panel.contains(e.target)&&!activeTrigger?.contains(e.target))hide();});
 
 function place(el){const host=el?.closest('.report-distribution')||el?.closest('svg')||el; if(host&&host!==panel)host.after(panel);panel.style.left='';panel.style.top='';}

 function taskDetail(t){panel.replaceChildren();const back=d.createElement('button');back.type='button';back.className='report-detail-back';back.textContent='← Tất cả công việc';back.onclick=()=>show(currentTitle,currentList,activeTrigger);panel.append(back);const card=d.createElement('article');card.className='report-task-detail';const h=d.createElement('h3'),meta=d.createElement('small');h.textContent=t.title;const done=(t.checks||[]).filter(c=>c.done).length;meta.textContent=[t.projectName,t.due?'Hạn '+t.due:'Chưa đặt hạn',(t.checks||[]).length?done+'/'+t.checks.length+' bước':null].filter(Boolean).join(' · ');card.append(h,meta);if(t.description){const p=d.createElement('p');p.textContent=t.description;card.append(p);}if((t.checks||[]).length){const ul=d.createElement('ul');for(const c of t.checks){const li=d.createElement('li');li.textContent=(c.done?'✓ ':'○ ')+c.text;ul.append(li);}card.append(ul);}else{const p=d.createElement('p');p.textContent='Chưa có checklist cho công việc này.';card.append(p);}panel.append(card);panel.hidden=false;place(activeTrigger||panel);}
 let currentTitle='',currentList=[];
 function show(title,list,el){clearTimeout(hideTimer);activeTrigger=el;currentTitle=title;currentList=list;panel.replaceChildren();const h=d.createElement('h2');h.textContent=title+' · '+list.length+' việc';panel.append(h);
 if(!list.length){const p=d.createElement('p');p.textContent=tasks.length?'Chưa có công việc.':'Tạo báo cáo mới để xem chi tiết.';panel.append(p);}
 for(const t of list){const item=d.createElement('button');item.type='button';item.className='report-task-pick';const name=d.createElement('strong'),meta=d.createElement('small');name.textContent=t.title;const done=(t.checks||[]).filter(c=>c.done).length;meta.textContent=[t.projectName,t.due?'Hạn '+t.due:'Chưa đặt hạn',(t.checks||[]).length?done+'/'+t.checks.length+' bước':null].filter(Boolean).join(' · ');item.append(name,meta);item.onclick=()=>taskDetail(t);panel.append(item);}
 panel.hidden=false;place(el);}
 function bind(el,title,list){el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label','Xem '+title);el.addEventListener('focus',()=>show(title,list(),el));el.addEventListener('blur',e=>{if(!panel.contains(e.relatedTarget))scheduleHide();});el.addEventListener('click',()=>show(title,list(),el));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(title,list(),el);}});}
 const groups=[['#3b8b61','done','Hoàn thành'],['#8054bf','doing','Đang xây dựng'],['#df8c40','todo','Chưa làm'],['#cd4c58','overdue','Quá hạn']];
 for(const [color,key,label] of groups){const list=()=>tasks.filter(t=>t.category===key);d.querySelectorAll('.report-donut circle[stroke="'+color+'"]').forEach(el=>bind(el,label,list));[...d.querySelectorAll('.report-distribution tr')].filter(r=>r.cells.length===2&&r.textContent.includes(label)).forEach(el=>bind(el,label,list));}
 const overall=d.querySelector('.report-sheet>table[role=presentation]+table');if(overall){const cells=overall.querySelectorAll('td');cells.forEach((el,i)=>bind(el,i===0?'Phần đã hoàn thành':'Phần còn lại',()=>tasks.filter(t=>cells.length===1?true:i===0?t.category==='done':t.category!=='done')));}
 d.querySelectorAll('.report-sheet>p').forEach(p=>{const text=p.textContent.trim();if(!text.startsWith('•'))return;const raw=text.slice(1).trim(),title=raw.split(' · ')[0],task=tasks.find(t=>t.title===title);if(!task)return;const next=p.nextElementSibling,nextText=next?.textContent.trim()||'',hint=nextText.startsWith('Bước tiếp:')?nextText.slice('Bước tiếp:'.length).trim():nextText;const button=d.createElement('button');button.type='button';button.className='report-suggestion-card';button.setAttribute('aria-label','Xem chi tiết: '+task.title);const name=d.createElement('strong'),due=d.createElement('span');name.textContent=task.title;due.className='report-due';due.textContent=task.due?'Hạn '+task.due:'Chưa đặt hạn';button.append(name,due);if(hint){const small=d.createElement('small');small.textContent=hint;button.append(small);}button.addEventListener('click',()=>{show('Chi tiết công việc',[task],button);taskDetail(task);});p.replaceWith(button);if(next?.textContent.trim().startsWith('Bước tiếp:')||next?.textContent.trim().startsWith('Xác định đầu ra'))next.remove();});
